import { Injectable } from '@angular/core';

/**
 * Interface définissant la structure de données d'un agriculteur.
 * Utilisée pour le typage dans toute l'application.
 */
export interface Agriculteur {
  id: number;
  nom: string;
  prenom: string;
  localisation: string;
  typeCulture: string;
  prixKilo: number;
  prixHectare: number;
  imageUrl: string;
  description?: string;
  telephone?: string;
}

@Injectable({
  providedIn: 'root',
})
export class AgriculteursService {
  /**
   * Simulation d'une base de données locale (Mock Data).
   * Ces données seront affichées sur la page d'accueil sous forme de cartes.
   */
  private listeAgriculteurs: Agriculteur[] = [
    {
      id: 1,
      nom: 'Sow',
      prenom: 'Moussa',
      localisation: 'Saint-Louis, Sénégal',
      typeCulture: 'Riz',
      prixKilo: 450,
      prixHectare: 300000,
      imageUrl:
        'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQPCMS9wl4xDIqpQn5H_TMzI9zX-RpT753s2g&s',
      description: 'Producteur de riz certifié dans la vallée du fleuve Sénégal.',
      telephone: ' 77 123 45 67',
    },
    {
      id: 2,
      nom: 'Diop',
      prenom: 'Fatou',
      localisation: 'Thiès, Sénégal',
      typeCulture: 'Cannes à sucre',
      prixKilo: 800,
      prixHectare: 150000,
      imageUrl:
        'data:image/jpeg;base64,',
      description: 'Producteur, expérimenté de Cannes en Sucre (30 ans d’expérience). ',
      telephone: ' 78 400 32 67',
    },
    {
      id: 3,
      nom: 'Ndiaye',
      prenom: 'Abdou',
      localisation: 'Casamance, Sénégal',
      typeCulture: 'Oignons',
      prixKilo: 1200,
      prixHectare: 500000,
      imageUrl:
        'data:image/jpeg;base64,',
      description:
        "Spécialiste de la culture d'oignons . Nos méthodes garantissent des bulbes fermes, bien colorés.",
      telephone: ' 70 467 23 23',
    },
    {
      id: 4,
      nom: 'Faye',
      prenom: 'Ibrahima',
      localisation: 'Dakar, Sénégal',
      typeCulture: 'Tomates',
      prixKilo: 600,
      prixHectare: 200000,
      imageUrl:
        'data:image/jpeg;base64,',
      description: 'Culture maraîchère moderne en zone périurbaine.',
      telephone: '77 104 35 90',
    },
  ];

  constructor() {}

  /**
   * Récupère la liste complète des agriculteurs pour la page d'accueil.
   * @returns Agriculteur[]
   */
  getAgriculteurs(): Agriculteur[] {
    return this.listeAgriculteurs;
  }

  /**
   * Récupère les détails d'un seul agriculteur via son identifiant unique.
   * @param id L'identifiant de l'agriculteur
   * @returns Agriculteur | undefined
   */
  getAgriculteurById(id: number): Agriculteur | undefined {
    return this.listeAgriculteurs.find((a) => a.id === id);
  }

  /**
   * Permet d'ajouter un nouvel agriculteur à la liste (utile pour un formulaire d'inscription).
   * @param agriculteur L'objet agriculteur à ajouter
   */
  addAgriculteur(agriculteur: Agriculteur): void {
    this.listeAgriculteurs.push(agriculteur);
  }

  /**
   * Permet de filtrer les agriculteurs par type de culture.
   * @param culture Le type de culture recherché
   * @returns Agriculteur[]
   */
  getAgriculteursByCulture(culture: string): Agriculteur[] {
    return this.listeAgriculteurs.filter((a) =>
      a.typeCulture.toLowerCase().includes(culture.toLowerCase()),
    );
  }
}
